import json
from pathlib import Path
p=Path('/output/candidate.json')
d=json.loads(p.read_text())
fn=d['j']['intent']['intent_function']
body=fn['body']
# Focused repair from the allowed observer diff: p5 is a bound true semantic
# constexpr, so preserve its J signature handle but specialize its consequence.
add=next(x for x in body if x.get('id')=='n3')
add['result']='t5'
add['type']={'dtype':'f32','shape':[2,'x0']}
fn['body']=[x for x in body if x.get('id')!='n4']
d['j']['node_ids'].pop('n4',None)
for a in d['j']['boundary']['accesses']:
    if a.get('access_id')=='a3':
        a['predicate']='0 <= k0 < x0'
    if a.get('access_id')=='a4':
        a['node_ref']='n3'
for e in d['j']['boundary']['effects']:
    if e.get('effect_id')=='e4':
        e['node_ref']='n3'
for q in d['j']['scopes']:
    q['definitions']=[x for x in q.get('definitions',[]) if x not in ('v3','n4')]
    q['captures']=[x for x in q.get('captures',[]) if x not in ('v3','n4')]
    q['effects']=[x for x in q.get('effects',[]) if x!='n4']
# Remove the runtime select/control realization and bridge the add result directly
# to the existing store transfer, then restore declaration-ordered i* IDs.
pi=d['pi']
inst_by={x['id']:x for x in pi['instances']}
bad={x['id'] for x in pi['instances'] if x['semantic_ref'] in {'t4','n4'}}
select_ids={x['id'] for x in pi['instances'] if x['semantic_ref']=='n4'}
new_routes=[]
for sid in select_ids:
    incoming=[r for r in pi['routes'] if r['target']==sid and r['source'] not in bad]
    outgoing=[r for r in pi['routes'] if r['source']==sid and r['target'] not in bad]
    for rin in incoming:
        if inst_by[rin['source']]['semantic_ref']!='n3':
            continue
        for rout in outgoing:
            nr={'source':rin['source'],'target':rout['target'],'slots':rout['slots']}
            if nr not in new_routes:
                new_routes.append(nr)
pi['instances']=[x for x in pi['instances'] if x['id'] not in bad]
pi['routes']=[r for r in pi['routes'] if r['source'] not in bad and r['target'] not in bad]
for r in new_routes:
    if r not in pi['routes']:
        pi['routes'].append(r)
# Order entries use only i* endpoint strings; drop entries touching removed stages.
pi['order']=[o for o in pi['order'] if not any(v in bad for v in o.values() if isinstance(v,str))]
clean=[]
for s in pi['sharing']:
    if s['source'] in bad: continue
    s=dict(s)
    s['consumers']=[x for x in s['consumers'] if x not in bad]
    if s['consumers']: clean.append(s)
pi['sharing']=clean
pi['refinements']=[r for r in pi['refinements'] if r['instance'] not in bad]
old_to_new={x['id']:f'i{k}' for k,x in enumerate(pi['instances'])}
for x in pi['instances']: x['id']=old_to_new[x['id']]
def remap(x):
    if isinstance(x,list):
        for y in x: remap(y)
    elif isinstance(x,dict):
        for k,v in list(x.items()):
            if isinstance(v,str) and v in old_to_new: x[k]=old_to_new[v]
            else: remap(v)
remap({'routes':pi['routes'],'order':pi['order'],'sharing':pi['sharing'],'refinements':pi['refinements']})
p.write_text(json.dumps(d,indent=2)+"\n")
print('removed pi IDs:', sorted(bad))
print('added direct routes before renumber:', new_routes)
PY
